#pragma once
#include <string>
#include "options.hpp"

namespace blitz::format {
	/** Format the source code of a program. The result is the same program: Only the white space, the case of keywords and
	 * the number of blank lines change. Throws std::runtime_error if the result would not be the same program, which would
	 * be a bug in the formatter.
	 */
	std::string format_source(std::string const& source, options const& with);

	/** Whether two sources are the same program: They have the same tokens, comments, and statements on the same lines, and
	 * differ only in white space, blank lines, line endings and the case of keywords.
	 */
	bool same_program(std::string const& a, std::string const& b);
} // namespace blitz::format
